for (const o of orders) {
  if (o.status !== 'delivered' || !String(o.date).startsWith('2025')) continue;
  for (const it of o.items) if (it.category === 'office') { sum += it.quantity * it.unitPrice; rows.push([o.id, it.name, it.quantity, it.unitPrice]); }
}
return {sum, rows, statuses:[...new Set(orders.map(o=>o.status))], cats:[...new Set(orders.flatMap(o=>o.items.map(i=>i.category)))]};

